macro.command:
// Hunting Horn — Item Macro for MidiQOL 12.4 / Foundry v12
// On Use: ItemMacro @ "Called before targeting is resolved (*)" / preTargeting

const esc = (value) => {
  const s = String(value ?? "");
  if (globalThis.Handlebars?.Utils?.escapeExpression) return Handlebars.Utils.escapeExpression(s);
  return s
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
};

console.log("Hunting Horn ItemMacro fired", {
  macroPass: args?.[0]?.macroPass ?? args?.[0]?.tag,
  activityName: workflow?.activity?.name ?? rolledActivity?.name,
  activityId: workflow?.activity?.identifier ?? rolledActivity?.identifier,
  item: item?.name,
  actor: actor?.name
});

const rolled = (typeof rolledActivity !== "undefined" && rolledActivity)
  ? rolledActivity
  : (workflow?.activity ?? args?.[0]?.activity ?? null);

const isRecital =
  rolled?.identifier === "recital"
  || rolled?.name === "Recital"
  || (rolled?.name ?? "").toLowerCase().includes("recital")
  || workflow?.activity?.identifier === "recital"
  || workflow?.activity?.name === "Recital";

if (!isRecital) {
  console.log("Hunting Horn ItemMacro: not Recital, skipping");
  return;
}

ui.notifications.info("Recital: abriendo Songbook…");

const actorDoc = actor
  ?? workflow?.actor
  ?? item?.actor
  ?? item?.parent
  ?? (typeof token !== "undefined" ? token?.actor : null);

if (!actorDoc) {
  ui.notifications.warn("Recital: no se encontró el actor.");
  return;
}

const isMelodyItem = (i) => {
  const flag = foundry.utils.getProperty(i, "flags.world.hh.isMelody");
  const id = String(i.system?.identifier ?? "");
  return flag === true
    || (i.type === "feat" && id.startsWith("melody-"))
    || /^melody of /i.test(i.name ?? "");
};

const isMelodyAura = (ef) => {
  const flag = foundry.utils.getProperty(ef, "flags.world.hh.isMelodyAura");
  return flag === true || /melody of/i.test(ef.name ?? "");
};

const melodies = actorDoc.items.filter(isMelodyItem);

if (!melodies.length) {
  ui.notifications.warn("Recital: no hay Melodies en el actor (importa Melody of Might / Swiftness).");
  return;
}

const optionsHtml = melodies.map(m =>
  `<option value="${m.id}">${esc(m.name)}</option>`
).join("");

const content = `
<form class="flexcol">
  <p>Activa una Melody del Songbook (aura 15 ft, 1 minuto).</p>
  <div class="form-group">
    <label>Melody</label>
    <div class="form-fields">
      <select id="hh-melody-select">${optionsHtml}</select>
    </div>
  </div>
</form>
`;

const selectedId = await new Promise((resolve) => {
  let settled = false;
  const done = (v) => { if (!settled) { settled = true; resolve(v); } };
  new Dialog({
    title: "Recital — Songbook",
    content,
    buttons: {
      ok: {
        icon: '<i class="fas fa-music"></i>',
        label: "Perform",
        callback: (html) => {
          try {
            const val = html?.find
              ? html.find("#hh-melody-select").val()
              : (html?.querySelector?.("#hh-melody-select")?.value
                ?? $(html).find("#hh-melody-select").val());
            done(val || null);
          } catch (e) {
            console.error(e);
            done(null);
          }
        }
      },
      cancel: {
        icon: '<i class="fas fa-times"></i>',
        label: "Cancel",
        callback: () => done(null)
      }
    },
    default: "ok",
    close: () => done(null)
  }).render(true);
});

if (!selectedId) {
  ui.notifications.warn("Recital cancelado.");
  return;
}

const selected = melodies.find(m => m.id === selectedId);
if (!selected) {
  ui.notifications.error("Recital: Melody no válida.");
  return;
}

const ops = [];
for (const mel of melodies) {
  for (const ef of mel.effects) {
    if (!isMelodyAura(ef)) continue;
    ops.push(ef.update({
      disabled: true,
      duration: { seconds: null, rounds: null, turns: null, startTime: null }
    }));
  }
}
for (const ef of actorDoc.effects) {
  if (!isMelodyAura(ef)) continue;
  ops.push(ef.update({
    disabled: true,
    duration: { seconds: null, rounds: null, turns: null, startTime: null }
  }));
}
if (ops.length) await Promise.all(ops);

const toEnable = selected.effects.filter(isMelodyAura);
if (!toEnable.length) {
  ui.notifications.error(`Recital: ${selected.name} no tiene Active Effect de aura.`);
  return;
}

const startTime = game.time.worldTime;
await Promise.all(toEnable.map(ef => ef.update({
  disabled: false,
  duration: {
    seconds: 60,
    startTime,
    rounds: null,
    turns: null,
    combat: null,
    startRound: null,
    startTurn: null
  }
})));

try {
  const sceneId = canvas.scene?.id;
  if (game.modules.get("ActiveAuras")?.active && sceneId) {
    if (globalThis.ActiveAuras?.CollateAuras) {
      await ActiveAuras.CollateAuras(sceneId, true, true, "hunting-horn-recital");
    } else if (globalThis.AAHelpers?.collateAuras) {
      await AAHelpers.collateAuras(sceneId, true, true, "hunting-horn-recital");
    }
  }
} catch (err) {
  console.warn("Recital: Active Auras refresh skipped", err);
}

await ChatMessage.create({
  speaker: ChatMessage.getSpeaker({ actor: actorDoc }),
  content: `<div class="dnd5e2"><p><strong>${esc(actorDoc.name)}</strong> performs <em>${esc(selected.name)}</em>.</p><p>15-foot aura active for 1 minute (or until Incapacitated / another Recital).</p></div>`
});
